      />
      <div className="grid gap-6 lg:grid-cols-3">
        <OverdueCard
          count={stats.overdueCount}
          today={formatCalendarDate(todayInMalaysia(now))}
        />
        <div className="lg:col-span-2">
          <CollectionsBars rows={collections} />
        </div>
      </div>
    </>
  );
};

