        <div className="mt-3 flex justify-end border-t pt-3">
          <Button
            type="button"
            variant="ghost"
            size="sm"
            onClick={picker.selectToday}
          >
            Today
          </Button>
        </div>
      </PopoverContent>
    </Popover>
  );
};

