import {
  ChevronLeft,
  ChevronRight,
  ChevronsLeft,
  ChevronsRight,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { type CalendarDay, WEEKDAY_LABELS } from "@/lib/calendar-grid";
import { formatCalendarDate } from "@/lib/dates";
import { cn } from "@/lib/utils";

type CalendarProps = {
  monthLabel: string;
  grid: readonly CalendarDay[];
  selected: string;
  today: string | null;
  onPrevMonth: () => void;
  onNextMonth: () => void;
  onPrevYear: () => void;
  onNextYear: () => void;
  onSelect: (date: string) => void;
};

const dayLabel = (day: CalendarDay, isToday: boolean) =>
  `${formatCalendarDate(day.date)}${isToday ? ", today" : ""}`;

// Presentational month view; state and grid come from useDatePicker.
export const Calendar = ({
  monthLabel,
  grid,
  selected,
  today,
  onPrevMonth,
  onNextMonth,
  onPrevYear,
  onNextYear,
  onSelect,
}: CalendarProps) => (
  <div className="flex flex-col gap-3">
    <div className="flex items-center justify-between gap-2">
      <div className="flex">
        <Button
          type="button"
          variant="ghost"
          size="icon-sm"
          onClick={onPrevYear}
          aria-label="Previous year"
        >
          <ChevronsLeft />
        </Button>
        <Button
          type="button"
          variant="ghost"
          size="icon-sm"
          onClick={onPrevMonth}
          aria-label="Previous month"
        >
          <ChevronLeft />
        </Button>
      </div>
      <p className="text-sm font-semibold tracking-tight" aria-live="polite">
        {monthLabel}
      </p>
      <div className="flex">
        <Button
          type="button"
          variant="ghost"
          size="icon-sm"
          onClick={onNextMonth}
          aria-label="Next month"
        >
          <ChevronRight />
        </Button>
        <Button
          type="button"
          variant="ghost"
          size="icon-sm"
          onClick={onNextYear}
          aria-label="Next year"
        >
          <ChevronsRight />
        </Button>
      </div>
    </div>
    <div className="grid grid-cols-7 gap-1 text-center">
      {WEEKDAY_LABELS.map((weekday) => (
        <span
          key={weekday}
          className="py-1 text-xs font-medium text-muted-foreground"
          aria-hidden
        >
          {weekday}
        </span>
      ))}
      {grid.map((day) => {
        const isSelected = day.date === selected;
        const isToday = day.date === today;
        return (
          <button
            key={day.date}
            type="button"
            onClick={() => onSelect(day.date)}
            aria-label={dayLabel(day, isToday)}
            aria-pressed={isSelected}
            aria-current={isToday ? "date" : undefined}
            className={cn(
              "flex size-9 items-center justify-center rounded-lg text-sm tabular-nums transition-colors outline-none hover:bg-secondary hover:text-secondary-foreground focus-visible:ring-3 focus-visible:ring-ring/50",
              !day.inMonth && "text-muted-foreground/60",
              isToday && "font-semibold text-primary ring-1 ring-primary/40",
              isSelected &&
                "bg-primary font-semibold text-primary-foreground shadow-sm shadow-primary/30 ring-0 hover:bg-primary hover:text-primary-foreground",
            )}
          >
            {day.day}
          </button>
        );
      })}
    </div>
  </div>
);

"use client";

import { CalendarDays } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Calendar } from "@/components/ui/calendar";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { cn } from "@/lib/utils";
import { useDatePicker } from "./use-date-picker";

type DatePickerProps = {
  id?: string;
  value: string; // 'YYYY-MM-DD' or ''
  onChange: (value: string) => void;
  placeholder?: string;
  invalid?: boolean;
  disabled?: boolean;
  className?: string;
};

export const DatePicker = ({
  id,
  value,
  onChange,
  placeholder = "Pick a date",
  invalid,
  disabled,
  className,
}: DatePickerProps) => {
  const picker = useDatePicker({ value, onChange });

  return (
    <Popover open={picker.open} onOpenChange={picker.onOpenChange}>
      <PopoverTrigger
        render={
          <Button
            id={id}
            type="button"
            variant="outline"
            disabled={disabled}
            aria-invalid={invalid ? true : undefined}
            className={cn(
              "w-full justify-start font-normal dark:bg-input/30",
              className,
            )}
          />
        }
      >
        <CalendarDays className="text-muted-foreground" />
        <span
          className={cn("truncate", !picker.label && "text-muted-foreground")}
        >
          {picker.label ?? placeholder}
        </span>
      </PopoverTrigger>
      <PopoverContent className="w-auto">
        <Calendar
          monthLabel={picker.monthLabel}
          grid={picker.grid}
          selected={picker.selected}
          today={picker.today}
          onPrevMonth={picker.prevMonth}
          onNextMonth={picker.nextMonth}
          onPrevYear={picker.prevYear}
          onNextYear={picker.nextYear}
          onSelect={picker.selectDate}
        />
        <div className="mt-3 flex justify-end border-t pt-3">
          <Button
            type="button"
            variant="ghost"
            size="sm"
            onClick={picker.selectToday}
          >
            Today
          </Button>
        </div>
      </PopoverContent>
    </Popover>
  );
};

"use client";

import { CalendarClock, Clock } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Calendar } from "@/components/ui/calendar";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { cn } from "@/lib/utils";
import { useDateTimePicker } from "./use-date-picker";

type DateTimePickerProps = {
  id: string;
  value: string; // 'YYYY-MM-DDTHH:mm' Malaysia wall clock, or ''
  onChange: (value: string) => void;
  placeholder?: string;
  invalid?: boolean;
  disabled?: boolean;
  className?: string;
};

const HOURS = Array.from({ length: 24 }, (_, h) => String(h).padStart(2, "0"));
const MINUTES = Array.from({ length: 60 }, (_, m) =>
  String(m).padStart(2, "0"),
);

const SELECT_CLASS =
  "h-8 rounded-lg border border-input bg-transparent px-2 text-sm tabular-nums outline-none focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 disabled:opacity-50 dark:bg-input/30";

export const DateTimePicker = ({
  id,
  value,
  onChange,
  placeholder = "Pick a date and time",
  invalid,
  disabled,
  className,
}: DateTimePickerProps) => {
  const picker = useDateTimePicker({ value, onChange });

  return (
    <Popover open={picker.open} onOpenChange={picker.onOpenChange}>
      <PopoverTrigger
        render={
          <Button
            id={id}
            type="button"
            variant="outline"
            disabled={disabled}
            aria-invalid={invalid ? true : undefined}
            className={cn(
              "w-full justify-start font-normal dark:bg-input/30",
              className,
            )}
          />
        }
      >
        <CalendarClock className="text-muted-foreground" />
        <span
          className={cn(
            "truncate tabular-nums",
            !picker.label && "text-muted-foreground",
          )}
        >
          {picker.label ?? placeholder}
        </span>
        <span className="ml-auto text-xs text-muted-foreground">MYT</span>
      </PopoverTrigger>
      <PopoverContent className="w-auto">
        <Calendar
          monthLabel={picker.monthLabel}
          grid={picker.grid}
          selected={picker.selected}
          today={picker.today}
          onPrevMonth={picker.prevMonth}
          onNextMonth={picker.nextMonth}
          onPrevYear={picker.prevYear}
          onNextYear={picker.nextYear}
          onSelect={picker.selectDate}
        />
        <fieldset className="mt-3 flex flex-col gap-2 border-t pt-3">
          <legend className="sr-only">Time</legend>
          <div className="flex items-center gap-2">
            <Clock className="size-4 text-muted-foreground" aria-hidden />
            <label htmlFor={`${id}-hour`} className="sr-only">
              Hour
            </label>
            <select
              id={`${id}-hour`}
              className={SELECT_CLASS}
              value={picker.hour}
              disabled={!picker.hasDate}
              onChange={(event) => picker.setHour(event.target.value)}
            >
              {HOURS.map((hour) => (
                <option key={hour} value={hour}>
                  {hour}
                </option>
              ))}
            </select>
            <span className="text-muted-foreground" aria-hidden>
              :
            </span>
            <label htmlFor={`${id}-minute`} className="sr-only">
              Minute
            </label>
            <select
              id={`${id}-minute`}
              className={SELECT_CLASS}
              value={picker.minute}
              disabled={!picker.hasDate}
              onChange={(event) => picker.setMinute(event.target.value)}
            >
              {MINUTES.map((minute) => (
                <option key={minute} value={minute}>
                  {minute}
                </option>
              ))}
            </select>
          </div>
          <p className="text-xs text-muted-foreground">
            Malaysia time (UTC+8)
          </p>
        </fieldset>
        <div className="mt-3 flex justify-between gap-2 border-t pt-3">
          <Button type="button" variant="ghost" size="sm" onClick={picker.setNow}>
            Now
          </Button>
          <Button type="button" size="sm" onClick={picker.close}>
            Done
          </Button>
        </div>
      </PopoverContent>
    </Popover>
  );
};

