        defaultValue={q}
        placeholder="Search by unit or tenant"
        aria-label="Search leases by unit or tenant"
        className="h-9 pl-9"
      />
    </div>
    <Button type="submit" variant="secondary" size="lg">
      Search
    </Button>
  </Form>
);

